SELECT id, username, password, real_name, phone, email, status, create_time, update_time
FROM sys_user
WHERE username = #{username}

SELECT id, username, password, real_name, phone, email, status, create_time, update_time
FROM sys_user
WHERE id = #{id}

SELECT id, username, password, real_name, phone, email, status, create_time, update_time FROM sys_user
username LIKE CONCAT('%', #{username}, '%')
ORDER BY id LIMIT #{limit} OFFSET #{offset}
